function initPoliticalVisualizer(){const e=document.querySelectorAll(".assembly-node"),t=document.getElementById("assembly-info-panel");if(!e.length||!t)return;const a={assembly:"<strong>Santhagara (Central Assembly Hall):</strong> The sovereign supreme assembly of Vaishali. It consisted of 7,707 clan chiefs (known as Rajas) who gathered to discuss foreign policy, treaties, war, and internal laws. Decisions were made using voting wood sticks (salakas), representing a remarkably early form of direct ballot democracy.",president:"<strong>Ganapramukh (President / Chief Consul):</strong> Elected by the assembly for a set term. The Ganapramukh presided over assembly debates, held chief executive authority, and represented the republic in international negotiations.",vp:"<strong>Uparaja (Vice-Consul / Deputy):</strong> Elected by the Rajas to support the Ganapramukh in daily governance, civil administration, and coordinating assembly councils.",military:"<strong>Senapati (Commander-in-Chief / General):</strong> Appointed by the assembly to lead the military forces. Responsible for the city fortifications (the triple concentric walls of Vaishali) and defense of the republic against imperial threats like Magadha.",treasury:"<strong>Bhandagarika (Chancellor of the Exchequer / Treasurer):</strong> Oversaw taxation, collection of agricultural revenues, trade guild regulations, and financial distributions for civic architecture, roads, and fortifications."};e.forEach(i=>{i.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),i.classList.add("active");const n=i.dataset.role;t.innerHTML=a[n]||"",window.innerWidth<768&&t.scrollIntoView({behavior:"smooth",block:"nearest"})})})}function initTimeline(){const e=document.getElementById("vaishali-timeline");if(!e)return;[{date:"c. 6th Century BCE",title:"Founding of the Vajji Republic",desc:"The Licchavis and neighboring clans unite to establish the Vajji Confederacy, setting up its capital in Vaishali. They build a democratic governance model based on popular assemblies."},{date:"599 BCE",title:"Birth of Lord Mahavira",desc:"Vardhamana Mahavira is born at Kundagrama, a suburb of Vaishali, to King Siddhartha and Queen Trishala. Vaishali becomes a seminal center of Jain spiritual thought."},{date:"c. 483 BCE",title:"Buddha's Last Sermon & Relic Division",desc:"Gautama Buddha delivers his final sermon at Vaishali, announcing his upcoming Mahaparinirvana. After his cremation, the Licchavis receive 1/8th of his ashes and build a mud stupa over them."},{date:"383 BCE",title:"The Second Buddhist Council",desc:"Convened by King Kalasoka in Vaishali to resolve doctrinal disputes regarding monastic rules, cementing Vaishali's position as a pillar of early Buddhist history."},{date:"c. 250 BCE",title:"Ashoka's Inscription & Monolithic Pillar",desc:"Mauryan Emperor Ashoka visits Vaishali, erects the famous polished sandstone pillar topped by a single lion, and builds a brick stupa beside the coronation tank."},{date:"c. 4th - 5th Century CE",title:"Gupta Dynasty & Travelogues",desc:"Vaishali continues to flourish under early Gupta administration, but Chinese pilgrim Faxian records its gradual decline. Later, Xuanzang (7th C) describes the city as mostly in ruins."},{date:"1861 CE",title:"Rediscovery by Alexander Cunningham",desc:"The founder of the Archaeological Survey of India identifies the modern village of Basarh in Bihar as ancient Vaishali, starting scientific excavations."},{date:"1958 - 1962 CE",title:"Relic Stupa Excavation",desc:"Archaeologist Dr. A. S. Altekar excavates the Relic Stupa and discovers the relic casket containing Buddha's ashes, now housed in the Patna Museum."}].forEach(t=>{const a=document.createElement("div");a.classList.add("timeline-node"),a.innerHTML=`\n            <div class="timeline-node-date">${t.date}</div>\n            <h3>${t.title}</h3>\n            <p>${t.desc}</p>\n        `,e.appendChild(a)})}document.addEventListener("DOMContentLoaded",()=>{initPoliticalVisualizer(),initTimeline(),initMonuments(),initInteractiveMap()});const monumentsData=[{id:"ashokan-pillar",name:"Ashokan Lion Pillar",type:"Buddhist / Mauryan",category:"buddhist",desc:"A pristine, single-piece polished sandstone monolithic pillar erected by Emperor Ashoka. Unlike other pillars, it features a single seated lion facing north, the direction Buddha took on his final journey. Beside the pillar sits the Ananda Stupa and a brick Coronation Tank."},{id:"relic-stupa",name:"Buddha Relic Stupa",type:"Buddhist / Archaeological",category:"buddhist",desc:"One of the eight original stupas constructed immediately after Buddha's death. Archaeological excavations here in 1958 unearthed a sacred grey soapstone relic casket containing cremated remains, conch shells, and punch-marked coins."},{id:"coronation-tank",name:"Abhisheka Pushkarini",type:"Archaeological / Vajji",category:"archaeological",desc:"A large ancient pond (reservoir) whose waters were considered sacred. Newly elected representatives (Rajas) of the Licchavi assembly had to bathe in this tank before taking their oaths of office at the Santhagara."},{id:"raja-vishal-garh",name:"Raja Vishal ka Garh",type:"Archaeological / Political",category:"archaeological",desc:"A massive fort mound covering over 80 acres, identified as the ancient parliament house of the Vajji Republic. Excavations uncovered brick ramparts, ring wells, and early historic pottery from the Mauryan and Shunga eras."},{id:"kundagram",name:"Kundalpur (Kundagram)",type:"Jain / Spiritual",category:"jain",desc:"Located close to main Vaishali, this site is historically identified as the birthplace of Lord Mahavira, the founder of modern Jainism. A beautiful temple stands here commemorating his birth and teachings."}];function initMonuments(){const e=document.getElementById("vaishali-monument-grid");e&&monumentsData.forEach(t=>{const a=document.createElement("div");a.classList.add("monument-explore-card");let i="arch-theme";"buddhist"===t.category&&(i="buddhist-theme"),"jain"===t.category&&(i="jain-theme"),a.classList.add(i),a.setAttribute("data-id",t.id),a.innerHTML=`\n            <span class="monument-type">${t.type}</span>\n            <h3>${t.name}</h3>\n            <p>${t.desc}</p>\n        `,a.addEventListener("click",()=>{highlightMapMarker(t.id)}),e.appendChild(a)})}const mapPins=[{id:"relic-stupa",name:"Buddha Relic Stupa",x:330,y:150,category:"buddhist"},{id:"ashokan-pillar",name:"Ashokan Lion Pillar",x:420,y:120,category:"buddhist"},{id:"coronation-tank",name:"Coronation Tank",x:440,y:200,category:"archaeological"},{id:"raja-vishal-garh",name:"Raja Vishal ka Garh",x:550,y:250,category:"archaeological"},{id:"kundagram",name:"Kundalpur (Mahavira Birthplace)",x:260,y:340,category:"jain"}];function initInteractiveMap(){const e=document.getElementById("vaishali-svg-map"),t=document.getElementById("map-marker-details"),a=document.querySelectorAll(".map-layer-btn");e&&t&&(mapPins.forEach(t=>{const a="buddhist"===t.category?"#eab308":"jain"===t.category?"#a855f7":"#3b82f6",i=document.createElementNS("http://www.w3.org/2000/svg","g");i.setAttribute("class",`map-marker ${t.category}`),i.setAttribute("id",`marker-${t.id}`),i.style.setProperty("--marker-glow",a);const n=document.createElementNS("http://www.w3.org/2000/svg","circle");n.setAttribute("cx",t.x),n.setAttribute("cy",t.y),n.setAttribute("r",8),n.setAttribute("fill","none"),n.setAttribute("stroke",a),n.setAttribute("stroke-width",2),n.setAttribute("class","map-marker-pulse");const s=document.createElementNS("http://www.w3.org/2000/svg","circle");s.setAttribute("cx",t.x),s.setAttribute("cy",t.y),s.setAttribute("r",7),s.setAttribute("fill",a);const r=document.createElementNS("http://www.w3.org/2000/svg","text");r.setAttribute("x",t.x+12),r.setAttribute("y",t.y+4),r.setAttribute("fill","#fff"),r.setAttribute("font-size","11"),r.setAttribute("font-family",'"Outfit", sans-serif'),r.setAttribute("font-weight","500"),r.textContent=t.name,i.appendChild(n),i.appendChild(s),i.appendChild(r),i.addEventListener("click",()=>{selectMarker(t.id)}),e.appendChild(i)}),a.forEach(t=>{t.addEventListener("click",()=>{a.forEach(e=>e.classList.remove("active")),t.classList.add("active");const i=t.dataset.layer;e.querySelectorAll(".map-marker").forEach(e=>{"all"===i||e.classList.contains(i)?(e.style.opacity="1",e.style.pointerEvents="auto"):(e.style.opacity="0.15",e.style.pointerEvents="none")})})}))}function selectMarker(e){const t=document.getElementById("map-marker-details"),a=monumentsData.find(t=>t.id===e);if(!a||!t)return;document.getElementById("vaishali-svg-map").querySelectorAll(".map-marker").forEach(e=>e.classList.remove("highlighted-pin")),document.getElementById(`marker-${e}`)?.classList.add("highlighted-pin");const i="buddhist"===a.category?"☸️":"jain"===a.category?"💎":"🏛️";t.innerHTML=`\n        <div style="text-align: left;">\n            <h4 style="margin: 0 0 6px; color: var(--vai-gold); font-size: 1.1rem; display: flex; align-items: center; gap: 8px;">\n                <span>${i}</span> ${a.name}\n            </h4>\n            <p style="margin: 0; font-size: 0.9rem; line-height: 1.45; color: var(--vai-text);">${a.desc}</p>\n        </div>\n    `;document.querySelectorAll(".monument-explore-card").forEach(e=>e.classList.remove("active-card"));const n=document.querySelector(`.monument-explore-card[data-id="${e}"]`);n&&(n.classList.add("active-card"),n.scrollIntoView({behavior:"smooth",block:"nearest"}))}function highlightMapMarker(e){selectMarker(e),document.querySelector(".interactive-map-box")?.scrollIntoView({behavior:"smooth",block:"center"})}